<table style="table-layout:fixed; width:100%; margin-top:10px; border-top:1px solid black; font-size:11px;">
    <tr style="border-bottom:1px solid black;">
        <td colspan="6" style=" padding:5px;">
            <b>Particulars</b>
        </td>
        {% for col in columns[1:] %}
            <td colspan="3" style="text-align:right; padding:5px;">
                <b>{{ col.label }}</b>
            </td>
        {% endfor %}
    </tr>

    {% for row in data %}
        {% set row_class = "" if (row.parent_account or row.parent_section) else "financial-statements-important" %}
        {% set row_class = row_class + ("" if (row.account_name or row.section) else " financial-statements-blank-row") %}

        <tr class="{{ row_class }}" style="{% if loop.index is odd %}background-color: #f9f9f9;{% endif %}">
            <td colspan="6" style="padding:4px;">
                {% if row.account %}
                    {% set is_group = frappe.db.get_value(
                        "Account",
                        row.account,
                        "is_group"
                    ) %}

                    {% if is_group == 1  %}
                        <span style="font-weight: 600;">
                            {{ row.account_name }}
                        </span>
                    {% else %}
                        <span>
                            {{ row.account_name }}
                        </span>
                    {% endif %}
                {% else %}
                    {{ row.section or '' }}
                {% endif %}

            </td>

            {% for col in columns[1:] %}
                <td colspan="3" style="text-align:right; padding:4px;">
                    {% set value = row.get(col.fieldname) %}
                    {% set currency = filters.presentation_currency or 'GHS' %}
                    {% if value is not none and value != "" and value != 0 %}
                    <span style="{% if is_group == 1 %}font-weight:600;{% endif %}">
                        {% if value | float < 0 %}
                            ({{ "{:,.2f}".format((value | float) | abs) }})
                        {% else %}
                            {{ "{:,.2f}".format(value | float) }}
                        {% endif %}
                    {% endif %}
                    </span>
                </td>
            {% endfor %}
        </tr>
    {% endfor %}
</table>


{% endif %}

